


export type CreateReportRequestInput = { /** Three-letter ISO 4217 currency. Reports never combine currencies. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; /** Exclusive report interval end instant. Format: date-time. */ "interval_end_at": string | globalThis.Date; /** Inclusive report interval start instant. Format: date-time. */ "interval_start_at": string | globalThis.Date; /** Choose tax_transactions_itemized_v1 for frozen Quaderno-backed collection and successful refund evidence. This export supports reconciliation and import. It is not a tax return, nexus decision, or filing instruction. */ "report_type": "gift_card_liability_v1" | "orders_itemized_v1" | "orders_itemized_v2" | "payments_itemized_v1" | "balance_transactions_itemized_v1" | "payouts_itemized_v1" | "tax_itemized_v1" | "tax_summarized_v1" | "merchant_billing_itemized_v1" | "tax_transactions_itemized_v1"; /** IANA timezone used for date bucketing. Defaults to UTC. */ "timezone"?: string; };
